    /** @private */
    this._currTransitionTime = 1;
    /** @private */
    this._totalTransitionTime = 1;
    /** @private */
    this._isTransitioning = false;
    /** @private */
    this._transitionInterruptionSource = ANIM_INTERRUPTION_NONE;
    /** @private */
    this._transitionPreviousStates = [];
    /** @private */
    this._timeInState = 0;
    /** @private */
    this._timeInStateBefore = 0;
