class SceneUtils {
  /**
   * Loads the scene JSON file from a URL.
   *
   * @param {string} url - URL to scene JSON.
   * @param {number} maxRetries - Number of http load retry attempts.
   * @param {Function} callback - The callback to the JSON file is loaded.
   */
  static load(url, maxRetries, callback) {
    if (typeof url === 'string') {
      url = {
        load: url,
        original: url
      };
    }
    http.get(url.load, {
      retry: maxRetries > 0,
      maxRetries: maxRetries
    }, (err, response) => {
      if (!err) {
        callback(err, response);
      } else {
        let errMsg = `Error while loading scene JSON ${url.original}`;
        if (err.message) {
          errMsg += `: ${err.message}`;
          if (err.stack) {
            errMsg += `\n${err.stack}`;
          }
        } else {
          errMsg += `: ${err}`;
        }
        callback(errMsg);
      }
    });
  }
}

class HierarchyHandler extends ResourceHandler {
  /**
   * @param {import('../app-base').AppBase} app - The running {@link AppBase}.
   */
  constructor(app) {
    super(app, 'hierarchy');
  }
  load(url, callback) {
    SceneUtils.load(url, this.maxRetries, callback);
  }
  open(url, data) {
    // prevent script initialization until entire scene is open
    this._app.systems.script.preloading = true;
    const parser = new SceneParser(this._app, false);
    const parent = parser.parse(data);

    // re-enable script initialization
    this._app.systems.script.preloading = false;
    return parent;
  }
}

